SELECT NULL, 'dos-platform', x.path, x.comp, x.perm, x.sort, 'active',
       x.pt, x.lay, x.kpi, x.intent, 'tenant', FALSE,
       x.tk, x.sk, x.dr, 'table', TRUE, FALSE, FALSE, x.sw
  FROM (VALUES
    ('/admin/dos','platform.dos-platform.overview','platform.dos.read',100,'overview','dashboard','module-overview','monitor','dos.overview.title','dos.overview.subtitle','dos.resource.overview','command-center.dos'),
    ('/admin/dos/schemas','platform.dos-platform.schemas','platform.dos.read',200,'list','full-page','none','manage','dos.e1.title','dos.e1.subtitle','dos.resource.schemas','smart-grid.dos'),
    ('/admin/dos/registries','platform.dos-platform.registries','platform.dos.read',300,'list','full-page','none','manage','dos.e2.title','dos.e2.subtitle','dos.resource.registries','smart-grid.dos'),
    ('/admin/dos/events','platform.dos-platform.events','platform.dos.read',400,'list','full-page','none','manage','dos.e3.title','dos.e3.subtitle','dos.resource.events','smart-grid.dos'),
    ('/admin/dos/audit','platform.dos-platform.audit','platform.dos.read',500,'audit','report','none','investigate','dos.audit.title','dos.audit.subtitle','dos.resource.audit','audit-timeline.dos')
  ) AS x(path, comp, perm, sort, pt, lay, kpi, intent, tk, sk, dr, sw)
 WHERE NOT EXISTS (
   SELECT 1 FROM dos.dynamic_ui_routes r
    WHERE r.tenant_id IS NULL AND r.module_code='dos-platform' AND r.path_pattern = x.path
 );
UPDATE dos.dynamic_ui_routes
   SET signature_widget = CASE
     WHEN path_pattern='/admin/dos'                THEN 'command-center.dos'
     WHEN path_pattern='/admin/dos/schemas'   THEN 'smart-grid.dos'
     WHEN path_pattern='/admin/dos/registries'   THEN 'smart-grid.dos'
     WHEN path_pattern='/admin/dos/events'   THEN 'smart-grid.dos'
     WHEN path_pattern='/admin/dos/audit'          THEN 'audit-timeline.dos'
   END,
   page_type = CASE
     WHEN path_pattern='/admin/dos'                THEN 'overview'
     WHEN path_pattern='/admin/dos/audit'          THEN 'audit'
     ELSE 'list' END,
   layout = CASE
     WHEN path_pattern='/admin/dos'                THEN 'dashboard'
     WHEN path_pattern='/admin/dos/audit'          THEN 'report'
     ELSE 'full-page' END,
   kpi_scope = CASE
     WHEN path_pattern='/admin/dos'                THEN 'module-overview'
     ELSE 'none' END
 WHERE module_code='dos-platform' AND tenant_id IS NULL;
