SELECT NULL, 'tenant-management', x.path, x.comp, x.perm, x.sort, 'active',
       x.pt, x.lay, x.kpi, x.intent, 'tenant', FALSE,
       x.tk, x.sk, x.dr, 'table', TRUE, FALSE, FALSE, x.sw
  FROM (VALUES
    ('/admin/tenants','platform.tenant-management.overview','platform.tenant.read',100,'overview','dashboard','module-overview','monitor','tm.overview.title','tm.overview.subtitle','tm.resource.overview','command-center.tm'),
    ('/admin/tenants/directory','platform.tenant-management.directory','platform.tenant.read',200,'list','full-page','none','manage','tm.e1.title','tm.e1.subtitle','tm.resource.directory','smart-grid.tm'),
    ('/admin/tenants/members','platform.tenant-management.members','platform.tenant.read',300,'list','full-page','none','manage','tm.e2.title','tm.e2.subtitle','tm.resource.members','smart-grid.tm'),
    ('/admin/tenants/profile','platform.tenant-management.profile','platform.tenant.read',400,'list','full-page','none','manage','tm.e3.title','tm.e3.subtitle','tm.resource.profile','smart-grid.tm'),
    ('/admin/tenants/audit','platform.tenant-management.audit','platform.tenant.read',500,'audit','report','none','investigate','tm.audit.title','tm.audit.subtitle','tm.resource.audit','audit-timeline.tm')
  ) AS x(path, comp, perm, sort, pt, lay, kpi, intent, tk, sk, dr, sw)
 WHERE NOT EXISTS (
   SELECT 1 FROM dos.dynamic_ui_routes r
    WHERE r.tenant_id IS NULL AND r.module_code='tenant-management' AND r.path_pattern = x.path
 );
UPDATE dos.dynamic_ui_routes
   SET signature_widget = CASE
     WHEN path_pattern='/admin/tenants'                THEN 'command-center.tm'
     WHEN path_pattern='/admin/tenants/directory'   THEN 'smart-grid.tm'
     WHEN path_pattern='/admin/tenants/members'   THEN 'smart-grid.tm'
     WHEN path_pattern='/admin/tenants/profile'   THEN 'smart-grid.tm'
     WHEN path_pattern='/admin/tenants/audit'          THEN 'audit-timeline.tm'
   END,
   page_type = CASE
     WHEN path_pattern='/admin/tenants'                THEN 'overview'
     WHEN path_pattern='/admin/tenants/audit'          THEN 'audit'
     ELSE 'list' END,
   layout = CASE
     WHEN path_pattern='/admin/tenants'                THEN 'dashboard'
     WHEN path_pattern='/admin/tenants/audit'          THEN 'report'
     ELSE 'full-page' END,
   kpi_scope = CASE
     WHEN path_pattern='/admin/tenants'                THEN 'module-overview'
     ELSE 'none' END
 WHERE module_code='tenant-management' AND tenant_id IS NULL;
